from .base import AppServerRunner
from .iperf_analyzer import IperfAnalyzer


class IperfDataTransfer(AppServerRunner):
    """Iperf Data Transfer"""
    def __init__(self, app_server_ip, app_server_username, app_server_password, app_server_lte_ip, logger, command_tail, **kwargs):
        """

        :param app_server_ip:
        :param app_server_username:
        :param app_server_password:
        :param app_server_lte_ip:
        :param logger:
        :param command_tail:
        :param logs_path:
        :param kwargs:
        """
        super(IperfDataTransfer, self).__init__(app_server_ip, app_server_username, app_server_password,
                                                app_server_lte_ip, logger)
        analyzer_params = kwargs.get('analyzer_params')
        self.command_tail = command_tail
        self.analyzer = IperfAnalyzer(logger, **analyzer_params)

    def run(self):
        """Run iperf command."""
        command = "iperf {}".format(self.command_tail)
        self._run_loop(command)
